def f(n):
    """Calculates f(n) = n / 2^m where 2^m is the largest power of 2 dividing n."""
    if n == 0:
        return 0 # Should not happen as n is positive
    m = 0
    temp = n
    while temp > 0 and temp % 2 == 0:
        m += 1
        temp //= 2
    return temp

def check_condition(u, v):
    """
    Checks if f(n+v) == f(n) (mod 4) for all n in {u, u+1, ..., u+v-1}.
    """
    for n in range(u, u + v):
        # We check f(n+v) - f(n) is a multiple of 4
        if (f(n + v) - f(n)) % 4 != 0:
            return False
    return True

def search_u(v, max_u):
    """Searches for u <= max_u such that the condition holds for the given v."""
    successful_pairs = []
    for u in range(1, max_u + 1):
        if check_condition(u, v):
            successful_pairs.append((u, v))
    return successful_pairs

